// Copyright 2016-2021 Crytek GmbH / Crytek Group. All rights reserved.#pragma once#include "Common/GraphicsPipelineStage.h"#include "Common/FullscreenPass.h"#include "Common/UtilityPasses.h"class CSunShaftsStage : public CGraphicsPipelineStage{public:	static const EGraphicsPipelineStage StageID = eStage_Sunshafts;	CSunShaftsStage(CGraphicsPipeline& graphicsPipeline)		: CGraphicsPipelineStage(graphicsPipeline)		, m_passShaftsMask(&graphicsPipeline)		, m_passShaftsGen0(&graphicsPipeline)		, m_passShaftsGen1(&graphicsPipeline) {}	// The two cvars, ANDed with the Cinematic Camera's suppression request on the post-effect bus	// (ReCS 2026-09-09: the screen-space shafts are retired under the camera; volumetric fog is the	// god-ray source). Note this gate never read the Time of Day's SunShafts_Active - that param	// only reaches the composite through SunShafts_Amount / RaysAmount - which is why pinning it	// from the camera did nothing. Every caller of the stage (the half-res downsample decision,	// Execute, and the tone map's featureMask / texture bind) goes through here, so one AND covers	// the whole chain. Flag 0 = byte-identical to stock.	bool IsStageActive(EShaderRenderingFlags flags) const final	{		if (!(CRenderer::CV_r_sunshafts && CRenderer::CV_r_PostProcess))			return false;		CPostEffectsMgr* pPostMgr = PostEffectMgr();		return !(pPostMgr && pPostMgr->GetByNameF("Global_User_SunShaftsSuppressed") > 0.5f);	}	void      Init() final;	void      Execute();	CTexture* GetFinalOutputRT();	void      GetCompositionParams(Vec4& params0, Vec4& params1);private:	CTexture* GetTempOutputRT();	int       GetDownscaledTargetsIndex();private:	CFullscreenPass m_passShaftsMask;	CFullscreenPass m_passShaftsGen0;	CFullscreenPass m_passShaftsGen1;};